package com.smartmart.ai.controller; import com.smartmart.ai.dto.AiRequest; import com.smartmart.ai.service.AiAssistantService; import com.smartmart.user.entity.User; import jakarta.validation.Valid; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/ai") @RequiredArgsConstructor public class AiController{private final AiAssistantService s;@PostMapping("/shopper") @PreAuthorize("hasRole('SHOPPER')") public Map<String,String> shopper(@AuthenticationPrincipal User u,@Valid @RequestBody AiRequest r){return Map.of("response",s.shopper(u,r));}@PostMapping("/manager") @PreAuthorize("hasRole('MANAGER')") public Map<String,String> manager(@Valid @RequestBody AiRequest r){return Map.of("response",s.manager(r));}}
